# Convert .env.test to JSON and send to CI secret sync endpoint
node -e "
const fs = require('fs');
const data = fs.readFileSync('.env.test', 'utf8');
const lines = data.split('\n').filter(line => line && !line.startsWith('#'));
const envVars = {};
lines.forEach(line => {
  const [key, value] = line.split('=');
  if (key && value) envVars[key] = value;
});
const jsonData = JSON.stringify(envVars);
console.log('Sending data:', jsonData);

// Send POST request
const https = require('http');
const postData = JSON.stringify({ secrets: envVars });

const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/ci-secret-sync',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

const req = https.request(options, (res) => {
  console.log(\`Status: \${res.statusCode}\`);
  res.on('data', (chunk) => {
    process.stdout.write(chunk);
  });
});

req.on('error', (e) => {
  console.error('Problem with request:', e.message);
});

req.write(postData);
req.end();
"

